contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 wait) public payable {
        require(address(this).balance >= amount);

        // Advance c's pastBlockTime if needed by making a valid call with a sufficient timestamp.
        // Any amount other than 10 ether reverts on the value check.
        if (amount != 10 ether) {
            bool revertedBadValue;
            try c.fallback{value: amount}() {
                revertedBadValue = false;
            } catch {
                revertedBadValue = true;
            }
            uint256 pastBeforeBad = c.pastBlockTime();
            bool revertedPastBad;
            try c.fallback{value: 10 ether}() {
                revertedPastBad = false;
            } catch {
                revertedPastBad = true;
            }
            assert(
                revertedBadValue &&
                c.pastBlockTime() == pastBeforeBad &&
                (revertedPastBad == (block.timestamp <= pastBeforeBad))
            );
            return;
        }

        uint256 pastBefore = c.pastBlockTime();
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 pastAfter = c.pastBlockTime();

        if (block.timestamp > pastBefore) {
            assert(!reverted && pastAfter == block.timestamp);
        } else {
            assert(reverted && pastAfter == pastBefore);
        }
    }

    receive() external payable {}
}

