        uint256 beforeBlockTime = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        // Drive the deciding call: if amount != 10 ether, this must revert.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After state read only through the public getter and balance.
        uint256 afterBlockTime = c.pastBlockTime();
