            amount != 10 ether
                ? (reverted && afterBlockTime == beforeBlockTime && afterBalance == beforeBalance)
                : (!reverted
                    ? (afterBlockTime > beforeBlockTime && afterBalance == beforeBalance + amount)
                    : (afterBlockTime == beforeBlockTime && afterBalance == beforeBalance))
        );
    }

    receive() external payable {}
}

