        // to the current block.timestamp (strictly greater than the previous value).
        // In this single-transaction test, block.timestamp is fixed; if beforeTime was
        // already the current timestamp the call must revert. Otherwise it must succeed.
        assert(
            (reverted && afterTime == beforeTime) ||
            (!reverted && afterTime == block.timestamp && afterTime > beforeTime)
        );
    }

    receive() external payable {}
}

