contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint64 newTimestamp) public payable {
        // Precondition: we will send exactly 10 ether, so the test contract must have that much.
        require(address(this).balance >= 10 ether);

        // Ensure the incoming timestamp is strictly greater than the current pastBlockTime
        // so the call is in the allowed condition. We intentionally restrict it to avoid
        // reverting on the timestamp requirement.
        require(newTimestamp > c.pastBlockTime());

        // Give the contract enough gas; the fallback will revert if block.timestamp is not greater than pastBlockTime.
        // We cannot control block.timestamp directly, but we can only require newTimestamp to be large enough
        // relative to the current pastBlockTime. The actual block.timestamp will be >= current time, and if
        // we choose a newTimestamp very large but the real block.timestamp is small, it may fail.
        // To make the test meaningful, we instead use the fact that we can only set pastBlockTime through a call.
        // However, we cannot set block.timestamp, so we rely on it being > 0 for initial state (pastBlockTime is 0).
        // The rule we assert is: if the call succeeds (does not revert), then pastBlockTime must be updated to
        // block.timestamp.

        bool reverted;
        uint balanceBefore = address(c).balance;
        uint pastBefore = c.pastBlockTime();

        // Make the deciding call: fallback with exactly 10 ether.
        // We cannot use try/catch on a fallback directly, so we use a low-level call.
        (bool success, ) = address(c).call{value: 10 ether}("");
        reverted = !success;

        // If the call did not revert, then pastBlockTime must have been updated to the current block timestamp.
        // Also, the balance of c must increase by 10 ether unless the block number condition triggered a payout.
        // Our rule focuses on pastBlockTime update, which is the general guarantee.
        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            // If it reverted, pastBlockTime must remain unchanged.
            assert(c.pastBlockTime() == pastBefore);
        }
    }

    receive() external payable {}
}

