contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 setupAmount) public payable {
        require(amount <= address(this).balance, "test contract lacks funds for amount");
        require(setupAmount <= address(this).balance - amount, "test contract lacks funds for setupAmount");

        // Setup: if setupAmount is positive, make an initial 10-ether setup call so that
        // pastBlockTime is as large as possible before the deciding call.
        bool setupReverted;
        if (setupAmount > 0) {
            require(setupAmount == 10 ether, "only the exact 10 ether setup path is meaningful");
            try c.fallback{value: setupAmount}() {
                setupReverted = false;
            } catch {
                setupReverted = true;
            }
        } else {
            setupReverted = false;
        }

        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        // Deciding call: drive c through its public fallback entry point.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPast = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        // General rule:
        // - If the value is not exactly 10 ether, the fallback must revert, must keep
        //   pastBlockTime unchanged, and must not change c's balance.
        // - If the value is exactly 10 ether, the fallback must succeed (no revert),
        //   and it must update pastBlockTime to the current block.timestamp. Since the
        //   timestamp is constant within a transaction, afterPast must equal block.timestamp.
        // - The balance change is exactly the amount sent, except that this test's
        //   single-transaction setup with block.number % 15 cannot safely assume the
        //   payout branch is inactive for an arbitrarily chosen deployment; therefore
        //   the exact balance delta is not asserted.
        assert(
            (amount != 10 ether && reverted && afterPast == beforePast && afterBalance == beforeBalance) ||
            (amount == 10 ether && !reverted && afterPast == block.timestamp)
        );
    }

    receive() external payable {}
}

