        //  instead infer failure from state and balance changes below.)
        uint256 afterTime = c.pastBlockTime();
        uint256 cBalAfter = address(c).balance;

        if (amount != 10 ether) {
            // A wrong value must not change the recorded time.
            assert(afterTime == priorTime);
            assert(cBalAfter == cBalBefore);
        } else {
            // A correctly-valued call advances the recorded time, and unless the contract
            // paid out its whole balance (block number divisible by 15), it keeps the sent 10 ether.
            assert(afterTime >= priorTime);
            assert(cBalAfter >= cBalBefore);
        }
