        bool reverted;
        (bool ok1, ) = address(c).call{value: amount}("");
        reverted = !ok1;

        uint256 afterTime = c.pastBlockTime();
        uint256 cBalAfter = address(c).balance;

        // General rule: the fallback reverts exactly when the sent value is not exactly
        // 10 ether; otherwise pastBlockTime strictly increases and the contract's balance
        // grows by the sent amount unless the block number is divisible by 15, in which
        // case it pays its whole balance to the caller (dropping its balance to zero).
        assert(
            reverted
                ? amount != 10 ether
                : (
                    amount == 10 ether
                        && afterTime > priorTime
                        && (block.number % 15 == 0 ? cBalAfter == 0 : cBalAfter == cBalBefore + amount)
                )
        );
    }
}

