contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, uint initValue, uint64 nextTime) public payable {
        require(amount >= 10 ether, "not enough ether sent");
        require(address(this).balance >= amount, "test contract balance too low");

        // Ensure the timestamp passed as the fallback call's block timestamp is
        // strictly greater than c's current pastBlockTime.
        // (The environment controls block.timestamp; the caller of run must choose
        // nextTime so that this precondition holds in the actual execution.)
        require(nextTime > c.pastBlockTime(), "timestamp not increasing");

        // Sanity/setup: calling fallback before is only possible after timestamp
        // precondition above. The deciding call is the single top-level fallback call.
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // If the call reverted, the value-transfer / state changes must not
            // have taken effect: c's balance is unchanged.
            assert(address(c).balance == beforeBalance);
        } else {
            // On completion the exactly-10-ether value was deposited; the
            // conditional payout can only happen when block.number % 15 == 0,
            // and then it drains the whole balance to msg.sender (the test).
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeBalance + 10 ether);
            }
        }
    }
}

