contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 time) public payable {
        require(address(this).balance >= amount);

        // Set up a prior pastBlockTime by making a successful fallback call with 10 ether and time t0,
        // provided we have enough balance and the condition on block.number will not cause a transfer that
        // drains the contract. We choose t0 such that t0 < time and t0 < block.timestamp. Since we cannot
        // control block.number, we allow the call to potentially transfer the balance; that's fine for setup.
        uint256 setupTime = time > 0 ? time - 1 : 0;
        if (setupTime >= block.timestamp) {
            setupTime = block.timestamp - 1;
        }
        // Only attempt setup if we have at least 10 ether available.
        if (address(this).balance >= 10 ether) {
            c.fallback{value: 10 ether}();
        }

        uint256 pastBefore = c.pastBlockTime();

        bool reverted;
        if (amount != 10 ether) {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
        } else {
            require(time > pastBefore, "time must be greater than pastBlockTime");
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            bool timeIncreased = time > pastBefore;
            bool valueOk = amount == 10 ether;
            assert(
                (timeIncreased && valueOk && !reverted) ||
                (!timeIncreased && reverted)
            );
        }
    }

    receive() external payable {}
}

