contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 firstTimestamp, uint256 secondTimestamp, uint256 secondValue) public payable {
        require(firstTimestamp > 0, "bad first timestamp");
        require(secondTimestamp > 0, "bad second timestamp");
        require(secondTimestamp != firstTimestamp, "timestamps must differ for the boundary test");
        require(address(this).balance >= 10 ether + secondValue, "insufficient balance");

        // First fallback call: exactly 10 ether, at firstTimestamp.
        uint256 beforeFirst = uint256(block.timestamp);
        (bool firstOk, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature(""));
        require(firstOk, "first 10 ether call should succeed");

        uint256 pastAfterFirst = c.pastBlockTime();

        // Second fallback call: parameterized value and timestamp.
        bool secondReverted;
        (bool secondOk, ) = address(c).call{value: secondValue}(abi.encodeWithSignature(""));
        secondReverted = !secondOk;

        // Snapshot the observable state after the second call.
        uint256 pastAfterSecond = c.pastBlockTime();

        // The fallback requires exactly 10 ether; a call with any other value must revert
        // and must not change pastBlockTime.
        if (secondValue != 10 ether) {
            assert(secondReverted && pastAfterSecond == pastAfterFirst);
            return;
        }

        // For exactly 10 ether, success is equivalent to the timestamp being strictly
        // greater than the recorded pastBlockTime; on success pastBlockTime advances to the
        // current timestamp, on failure it is left unchanged.
        if (secondTimestamp > firstTimestamp) {
            assert(!secondReverted);
            assert(pastAfterSecond >= firstTimestamp);
        } else {
            assert(secondReverted);
            assert(pastAfterSecond == pastAfterFirst);
        }
    }

    receive() external payable {}
}

